+err_helpers:
+	sw_fl_deinit();
+err_fib:
+	otx2_sw_fib_deinit();
+err_fdb:
+	sw_fdb_deinit();
+err_clear:
+	sw_nb_pf_netdev = NULL;
+	return err;
 }
+EXPORT_SYMBOL(otx2_sw_nb_register);
 
 #endif
